// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_DAO = address(0x123);

    function setUp() public { 
        vm.prank(INITIAL_DAO);
        c = new C(INITIAL_DAO); 
    }

    function testFuzz_property(address sender, address target, bool emergency) public {
        vm.assume(sender != address(0));

        // Call assertGovernanceApproved through the DAO
        vm.prank(INITIAL_DAO);
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency)
        );

        // After any call, the DAO should still be the initial address
        assertTrue(c.DAO() == INITIAL_DAO, "DAO changed after assertGovernanceApproved");
    }
}

